package io.github.yuejie.connect;

import android.app.Service;
import android.content.Intent;
import io.github.libxposed.api.XposedInterface.HookHandle;
import io.github.libxposed.api.XposedModule;
import java.util.ArrayList;
import java.util.List;

/** Guards only the real launcher clicks generated by OplusRelayDirectory. Ordinary OEM clicks are untouched. */
final class OplusRelayClickAdapter implements AutoCloseable {
    private final XposedModule module;
    private final ClassLoader loader;
    private final AppRelayNativeDelegate delegate;
    private final List<HookHandle> hooks = new ArrayList<>();
    private volatile boolean closed;
    private final java.util.concurrent.ThreadPoolExecutor worker = new java.util.concurrent.ThreadPoolExecutor(1, 1, 0,
            java.util.concurrent.TimeUnit.SECONDS, new java.util.concurrent.ArrayBlockingQueue<>(8), r -> {
                Thread thread = new Thread(r, "yj-oplus-relay-click"); thread.setDaemon(true); return thread;
            });
    OplusRelayClickAdapter(XposedModule module, ClassLoader loader, AppRelayNativeDelegate delegate) {
        this.module = module; this.loader = loader; this.delegate = delegate;
    }
    void install() throws ReflectiveOperationException {
        Class<?> service = Class.forName("com.oplus.synergy.service.SynergyCoreService", false, loader);
        Class<?> config = Class.forName("com.oplus.synergy.utils.Config", false, loader);
        String action = (String) config.getField("ACTION_APPLICATION_RELAY_SOURCE_CLICK").get(null);
        String type = (String) config.getField("KEY_RELAY_TYPE").get(null), remind = (String) config.getField("RELAY_EXTEND_KEY_REMIND_TYPE").get(null);
        String source = (String) config.getField("KEY_RELAY_SOURCE_PKG_NAME").get(null);
        try {
            hooks.add(module.hook(service.getDeclaredMethod("onStartCommand", Intent.class, int.class, int.class))
                    .setId("yj.oplus.relay.selected-click").intercept(chain -> {
                Intent intent = (Intent) chain.getArg(0);
                if (intent == null || !action.equals(intent.getAction()) || !delegate.isGatewayClick(intent)) return chain.proceed();
                if (closed) return Service.START_NOT_STICKY;
                AppRelayPeer peer = delegate.selectedClick(intent);
                if (peer == null || intent.getIntExtra(type, -1) != 1 || !"2".equals(intent.getStringExtra(remind)))
                    return Service.START_NOT_STICKY;
                String pkg = intent.getStringExtra(source);
                AppRelayCatalog.Candidate candidate = delegate.candidate(peer, pkg);
                if (candidate == null) return Service.START_NOT_STICKY;
                Service owner = (Service)chain.getThisObject();
                Intent click = new Intent(intent);
                AppRelayEvents.emit(AppRelayEvents.Event.NATIVE_CLICK, "oplus-click", AppRelayEvents.Outcome.PENDING);
                try { worker.execute(() -> {
                    try {
                        OplusRelayPermission.checkConsent(owner, loader);
                        if (candidate.kind() != AppRelayCatalog.Kind.BROWSER) OplusRelayPermission.checkAbility(loader, pkg);
                        if (closed || !peer.equals(delegate.selectedClick(click))) return;
                        delegate.requestSync(peer, pkg).whenComplete((result, error) -> {
                            if (result != null) AppRelayEvents.emit(AppRelayEvents.Event.NATIVE_CLICK_RESULT, result.requestId(), AppRelayEvents.outcome(result));
                            if (error != null || result == null || result.state() != AppRelayTasks.State.COMPLETED)
                                android.util.Log.w("YueJieRelay", "native_sync_failed");
                        });
                    } catch (Exception unavailable) { android.util.Log.w("YueJieRelay", "native_sync_unavailable"); }
                }); } catch (java.util.concurrent.RejectedExecutionException busy) { android.util.Log.w("YueJieRelay", "native_sync_busy"); }
                // Only this directory's click uses the gateway DATA channel. The stock path
                // would require ONet and broadcast the request to OEM peers.
                return Service.START_NOT_STICKY;
            }));
        } catch (ReflectiveOperationException | RuntimeException failure) { close(); throw failure; }
    }
    @Override public void close() { closed = true; for (HookHandle hook : hooks) hook.unhook(); hooks.clear(); worker.shutdown(); }
}
